```javascript
// transcribeUtil.js
import { TranscribeStreamingClient, StartStreamTranscriptionCommand } from "@aws-sdk/client-transcribe-streaming";
import { RecordActivity } from "@aws-sdk/util-utf8-browser";
import { EventStreamMarshaller } from "@aws-sdk/eventstream-marshaller";

const eventStreamMarshaller = new EventStreamMarshaller(RecordActivity.utm8NoBOM.encoder, RecordActivity.utm8NoBOM.decoder);

async function transcribe(audioSource, onTranscription, config) {
  // Set up AWS Transcribe Streaming Service client
  const transcribeClient = new TranscribeStreamingClient(config);

  // Create a StartStreamTranscriptionCommand with the required configuration
  const startStreamTranscriptionCommand = new StartStreamTranscriptionCommand({
    LanguageCode: "en-US",
    MediaEncoding: "pcm",
    MediaSampleRateHertz: 16000,
    AudioStream: {
      [Symbol.asyncIterator]: async function* () {
        for await (const chunk of audioSource) {
          const input = eventStreamMarshaller.marshall({AudioEvent: {AudioChunk: chunk}});
          yield {value: input};
        }
      }
    }
  });

  try {
    const response = await transcribeClient.send(startStreamTranscriptionCommand);
    for await (const event of response.TranscriptResultStream) {
      const message = eventStreamMarshaller.unmarshall(Buffer.from(event));
      if (message.TranscriptEvent) {
        const transcript = message.TranscriptEvent.Transcript.Results[0].Alternatives[0].Transcript;
        onTranscription(transcript);
      }
    }
  } catch (err) {
    console.error("Error transcribing: ", err);
  }
}

export { transcribe };
```

