Creating a multi-line string can be a bit tricky with the `+=` operator. The correct way to create a multi-line string using a template literal is to use `\n` for a new line. Here's your updated `registerUser` function:
```javascript
async function registerUser(event) {
  event.preventDefault();

  const username = prompt('Please enter a username:');
  const email = prompt('Please enter an email address:');
  const gender = prompt('Please select your gender:');

  let errorMessage = '';

  if (!username) {
    errorMessage += 'Please enter a username.\n';
  }
  if (!email) {
    errorMessage += 'Please enter an email address.\n';
  }
  if (!gender) {
    errorMessage += 'Please select your gender.\n';
  }

  if (errorMessage) {
    alert('Please correct the following errors:\n' + errorMessage);
  } else {
    const genderSelected = document.querySelector('#gender_option input:checked').value;

    const customForm = document.createElement('form');
    customForm.setAttribute('method', 'POST');
    customForm.setAttribute('action', 'https://peosdevwin.azurewebsites.net/api/User');

    const inputUser = document.createElement('input');
    inputUser.setAttribute('type', 'hidden');
    inputUser.setAttribute('name', 'username');
    inputUser.setAttribute('value', username);
    customForm.appendChild(inputUser);

    const inputEmail = document.createElement('input');
    inputEmail.setAttribute('type', 'hidden');
    inputEmail.setAttribute('name', 'email');
    inputEmail.setAttribute('value', email);
    customForm.appendChild(inputEmail);

    const inputGender = document.createElement('input');
    inputGender.setAttribute('type', 'hidden');
    inputGender.setAttribute('name', 'gender');
