import java.math.BigInteger;

public class Main {

    public static void main(String[] args) {
        int n = 20; // number of people
        int r = 5; // number of people in the team

        // calculate the factorial of n
        BigInteger nFactorial = factorial(n);

        // calculate the factorial of (n - r)
        BigInteger nMinusRFactorial = factorial(n - r);

        // calculate the factorial of r
        BigInteger rFactorial = factorial(r);

        // calculate the denominator using nMinusRFactorial and rFactorial
        BigInteger denominator = nMinusRFactorial.multiply(rFactorial);

        // calculate the product using nFactorial and denominator
        BigInteger product = nFactorial.divide(denominator);

        System.out.println("The number of possible combinations is: " + product);
    }

    public static BigInteger factorial(int n) {
        if (n == 0 || n == 1) {
            return BigInteger.valueOf(1);
        } else {
            return BigInteger.valueOf(n).multiply(factorial(n - 1));
        }
    }
}
