```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"sync"
)

type ResponseData struct {
	URL  string `json:"url"`
	Data string `json:"data"`
}

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Please provide at least one URL as an argument.")
		os.Exit(1)
	}

	urls := os.Args[1:]
	var wg sync.WaitGroup
	resultCh := make(chan ResponseData, len(urls))

	for _, url := range urls {
		wg.Add(1)
		go fetchURLData(url, resultCh, &wg)
	}

	// Wait for all goroutines to finish
	wg.Wait()
	close(resultCh)

	// Collect results from channel and marshal to JSON
	results := make([]ResponseData, 0, len(urls))
	for result := range resultCh {
		results = append(results, result)
	}

	jsonData, err := json.MarshalIndent(results, "", "  ")
	if err != nil {
		fmt.Println("Error marshalling results to JSON:", err)
		os.Exit(1)
	}

	// Write JSON data to output file
	err = ioutil.WriteFile("output.json", jsonData, 0644)
	if err != nil {
		fmt.Println("Error writing JSON data to file:", err)
		os.Exit(1)
	}

	fmt.Println("Results have been stored in output.json!")
}

func fetchURLData(url string, resultCh chan<- ResponseData, wg *sync.WaitGroup) {
	defer wg.Done()

	resp, err := http.Get(url)
	if err != nil {
		fmt.Printf("Error fetching %s: %v\n", url, err)
		return
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		fmt.Printf("Error reading response of %s: %v\n", url, err)
		return
	}

	resultCh <- ResponseData{
		URL:  url,
		Data: string(body),
	}
}
```

