  if (sum(one_flowers > width) > 0) {
    next
  }

  # Check if the total height of the 1-square meter flowers is less than or equal to the height of the garden bed
  if (sum(one_flowers > height) > 0) {
    next
  }

  # Check if there are no overlaps between the positions of the 1-square meter flowers
  if (any_overlap(one_flowers, width)) {
    next
  }

  # Check if there are no overlaps between the positions of the 2-square meter flowers
  if (any_overlap(two_flowers, width)) {
    next
  }

